import os
import re

DIRETORIO_SCRIPT = os.path.dirname(os.path.abspath(__file__))
PASTA_LABS = os.path.join(DIRETORIO_SCRIPT, "labs")

def search(diretorio_base=PASTA_LABS):
    if not os.path.isdir(diretorio_base):
        print(f"\033[1;31mErro: O diretório '{diretorio_base}' não existe no caminho atual.\033[0m")
        return []

    print(f"Iniciando varredura em: {diretorio_base}")
    print("-" * 50)

    itens = os.listdir(diretorio_base)
    pastas = [item for item in itens if os.path.isdir(os.path.join(diretorio_base, item))]
    pastas.sort()

    for pasta in pastas:
        caminho_pasta = os.path.join(diretorio_base, pasta)
        caminho_dockerfile_1 = os.path.join(caminho_pasta, "Dockerfile")
        caminho_dockerfile_2 = os.path.join(caminho_pasta, "dockerfile")
        
        if os.path.isfile(caminho_dockerfile_1) or os.path.isfile(caminho_dockerfile_2):
            print(f"📁 Pasta: \033[1;34m{pasta:<20}\033[0m | 🐳 Dockerfile: \033[1;32m[ ENCONTRADO ]\033[0m")
        else:
            print(f"📁 Pasta: \033[1;34m{pasta:<20}\033[0m | 🐳 Dockerfile: \033[1;31m[ NÃO ENCONTRADO ]\033[0m")
            
    print("-" * 50)
    print("Varredura concluída.")
    return pastas

