def playMenu():
    os.system('cls' if os.name == 'nt' else 'clear')
    print("\n\033[1;32m=== PLAY MENU - SELECIONE UM LABORATÓRIO ===\033[0m\n")
    
    pastas_disponiveis = search(diretorio_base=PASTA_LABS)
    
    if not pastas_disponiveis:
        print("\n\033[1;31mNenhum laboratório disponível para iniciar.\033[0m")
        input("Pressione ENTER para voltar ao menu principal...")
        return

    print("\nQual laboratório você deseja rodar?\n")
    
    for i, pasta in enumerate(pastas_disponiveis, start=1):
        print(f"\033[1;36m[ {i} ]\033[0m {pasta}")
        
    print(f"\033[1;31m[ 0 ]\033[0m Voltar")
    print("\n")
    
    escolha = input("Selecione o número da opção: ")
    
    if escolha == '0':
        return 
        
    try:
        indice = int(escolha) - 1
        
        if 0 <= indice < len(pastas_disponiveis):
            lab_escolhido = pastas_disponiveis[indice]
            caminho_lab = os.path.join(PASTA_LABS, lab_escolhido)
            
            print(f"\n\033[1;32mIniciando o laboratório: {lab_escolhido}...\033[0m")
            
            caminho_compose_yml = os.path.join(caminho_lab, "docker-compose.yml")
            caminho_compose_yaml = os.path.join(caminho_lab, "docker-compose.yaml")
            
            if os.path.isfile(caminho_compose_yml) or os.path.isfile(caminho_compose_yaml):
                print("\033[1;33m[ Docker Compose detectado ]\033[0m")
                comando_up = f'cd "{caminho_lab}" && docker compose up -d'
                comando_down = f'cd "{caminho_lab}" && docker compose down'
            else:
                print("\033[1;33m[ Apenas Dockerfile detectado. Executando build e run... ]\033[0m")
                nome_base = lab_escolhido.lower().replace(" ", "_")
                nome_img = re.sub(r'[^a-z0-9_.-]', '', nome_base)
                nome_container = f"{nome_img}_app" 
                
                comando_up = f'cd "{caminho_lab}" && docker build -t {nome_img} . && docker run -d --name {nome_container} {nome_img}'
                comando_down = f'docker rm -f {nome_container}'
                
            os.system(comando_up)
            
            print(f"\n\033[1;32mLaboratório '{lab_escolhido}' rodando em background!\033[0m")
            
            input("\n\033[1;33m>>> Pressione ENTER quando terminar para DERRUBAR a máquina... <<<\033[0m\n")
            
            print(f"\n\033[1;31mDerrubando o laboratório '{lab_escolhido}'...\033[0m")
            os.system(comando_down)
            
            print("\n\033[1;32mMáquina encerrada com sucesso!\033[0m")
            input("Pressione ENTER para voltar ao menu...")
            
        else:
            print("\n\033[1;31mOpção inválida! Número fora da lista.\033[0m")
            input("Pressione ENTER para tentar novamente...")
            
    except ValueError:
        print("\n\033[1;31mEntrada inválida! Digite apenas números.\033[0m")
        input("Pressione ENTER para tentar novamente...")

